type Tile = {
  key: string;
  label: string;
  blurb: string;
  tag: string;
  href?: string;
  mark: ReactNode;
};

const TILES: Tile[] = [
  {
    key: "fiserv",
    label: "Fiserv",
    blurb: "Fortune 500 payments and core banking provider",
    tag: "Payments",
    mark: <FiservMark />,
  },
  {
    key: "sbi",
    label: "SBI",
    blurb: "One of the world's largest banks, serving 500M+ customers",
    tag: "Banking",
    mark: <SbiMark />,
  },
  {
    key: "patelco",
    label: "Patelco",
    blurb: "One of the largest credit unions by membership",
    tag: "Banking",
    mark: <PatelcoMark />,
  },
  {
    key: "payjoy",
    label: "PayJoy",
    blurb: "Smartphone credit for 20M+ people",
    tag: "Lending",
    mark: <PayjoyMark />,
  },
  {
    key: "manipal-cigna",
    label: "Manipal Cigna",
    blurb: "Joint venture of Manipal Group and Cigna",
    tag: "Insurance",
    href: "/customers/manipal-cigna",
    mark: <ManipalCignaMark />,
  },
];

const TILE =
  "not-typeset flex h-full min-h-0 flex-col gap-3 p-4 text-black transition hover:opacity-90 sm:p-6 md:p-7";

function TileInner({ tile }: { tile: Tile }) {
  return (
    <>
      <div
        className="flex h-14 items-center [&_svg]:h-7 [&_svg]:w-auto [&_svg]:max-w-full [&_svg]:opacity-90"
        role="img"
        aria-label={tile.label}
      >
        {tile.mark}
      </div>
      <p className="!m-0 max-w-[32ch] flex-1 text-[14px] leading-[1.45] text-black/55 text-pretty md:text-[15px]">
        {tile.blurb}
      </p>
      <span className="mt-auto pt-3.5 font-[family-name:var(--font-mono)] text-[12px] font-medium tracking-[-0.02em] text-black/45 uppercase">
        {tile.tag}
      </span>
    </>
  );
}

export default function CustomerLogos() {
  return (
    <section aria-label="Our customers" className="not-typeset" data-not-typeset>
      <ul className="m-0 grid list-none grid-cols-1 gap-3 p-0 sm:grid-cols-2 sm:gap-3.5 lg:grid-cols-3">
        {TILES.map((tile) => {
          const body = <TileInner tile={tile} />;
          if (tile.href) {
            return (
              <li key={tile.key} className="min-w-0">
                <TransitionLink
                  href={tile.href}
                  className={`${TILE} no-underline hover:no-underline`}
                >
                  {body}
                </TransitionLink>
              </li>
            );
          }
          return (
            <li key={tile.key} className={`min-w-0 ${TILE}`}>
              {body}
            </li>
          );
        })}
        <li className={`min-w-0 ${TILE}`}>
          <div className="flex h-14 items-end font-[family-name:var(--font-mono)] text-[clamp(2.5rem,4vw,3.5rem)] font-medium leading-none tracking-[-0.03em] text-black">
            20<span className="text-black/45">+</span>
          </div>
          <p className="!m-0 max-w-[32ch] flex-1 text-[14px] leading-[1.45] text-black/55 md:text-[15px]">
            institutions run on Osfin
          </p>
          <span className="mt-auto pt-3.5 font-[family-name:var(--font-mono)] text-[12px] font-medium tracking-[-0.02em] text-black/45 uppercase">
            Banks · Fintechs · Insurers
          </span>
        </li>
      </ul>
    </section>
  );
}
